def score_words(words,Ls=range(20,36),k=4):
    ids=[tok.encode(w).ids[0] for w in words]
    tot=torch.zeros(len(ids))
    for L in Ls:
        for m in ['mlp.down_proj','self_attn.o_proj']:
            S,Vh,_=svd_lora(f'model.layers.{L}.{m}')
            Z=(E@(Vh.T*normw[:,None])); Z=(Z-Z.mean(0))/Z.std(0)
            sc=(Z.abs()[:, :k]).max(1).values
            r=torch.argsort(torch.argsort(-sc))
            tot+=torch.log10(r[ids].float()+1)
    n=len(list(Ls))*2
    for w,t in sorted(zip(words,tot.tolist()),key=lambda x:x[1]): print(repr(w),round(t/n,2))
